mapper.delete:
DELETE FROM ${tableName}
WHERE primary_key = #{productSeriesCode}
    and enterprise_code = #{enterpriseCode}
    and has_child = false
    and synchronize_status = 0
    and delete_flag = false

mapper.update:
UPDATE  ${tableName}
SET delete_flag = true,
    synchronize_status = 5
WHERE primary_key = #{productSeriesCode}
  and enterprise_code = #{enterpriseCode}
  and has_child = false
  and synchronize_status > 0
  and delete_flag = false

