  ORDER BY create_time ASC

SELECT 
FROM ${tableName}
WHERE delete_flag = false
  AND enterprise_code = #{enterpriseCode}
  AND superior = #{productSeriesCode}

WITH RECURSIVE ProductSeries AS (
    SELECT primary_key, product_series_sign, superior ,has_child
    FROM ${tableName}
    WHERE primary_key = #{productSeriesCode}
    UNION ALL
    SELECT t.primary_key, t.product_series_sign, t.superior,t.has_child
    FROM ${tableName} t
    INNER JOIN ProductSeries pt ON t.superior = pt.primary_key
)
SELECT * FROM ProductSeries

